/** AudioWorklet DSP path.
 *
 * The Web Audio graph in `audio.ts` is built from browser-supplied nodes, which
 * is the right default: they run on the audio thread in native code and cost
 * nothing to wire up. What they cannot do is arbitrary per-sample maths, and a
 * game eventually wants some — radio chatter, a damaged-hearing filter, a retro
 * bleep. That is what `AudioWorklet` is for.
 *
 * Two decisions shape this module.
 *
 * **The maths lives in a plain function.** {@link processCrush} takes an input
 * buffer, an output buffer, parameters, and a carry-over state object. It
 * touches no audio graph, so it can be unit-tested headlessly and the worklet
 * source is generated by embedding the function's own text — one implementation,
 * not one for the audio thread and a second one for the tests to check.
 *
 * **The fallback is explicit.** `audioWorklet` is missing in older Safari, in
 * insecure contexts, and in every headless test environment. Rather than
 * throwing or silently muting, {@link createDspNode} degrades in a documented
 * order: `worklet` -> `script-processor` (deprecated but universal, and it runs
 * the identical function) -> `bypass` (a pass-through gain). The chosen mode is
 * reported on the node, so a game can tell the player their browser is not
 * getting the effect instead of wondering why it sounds wrong.
 */

/** Sample-crushing parameters. Defaults are a no-op passthrough at `mix: 0`. */
export interface CrushParameters {
  /** Quantization depth in bits, clamped to `[1, 16]`. */
  readonly bits: number;
  /** Sample-and-hold factor; 4 means one new sample in every four. */
  readonly reduction: number;
  /** Pre-gain into the soft clip. Above 1 saturates. */
  readonly drive: number;
  /** Dry/wet blend in `[0, 1]`. */
  readonly mix: number;
}

/** Carry-over between blocks. A worklet gets 128 samples at a time, so the
 * sample-and-hold value and its countdown have to survive the block boundary. */
export interface CrushState {
  hold: number;
  phase: number;
}

export const DEFAULT_CRUSH_PARAMETERS: CrushParameters = Object.freeze({
  bits: 8,
  reduction: 4,
  drive: 1,
  mix: 1,
});

/** Processor name registered inside the worklet global scope. */
export const CRUSH_PROCESSOR_NAME = "vapour-crush" as const;

/**
 * Bit-crush and sample-rate-reduce one block of mono audio.
 *
 * Deterministic: the same input, parameters, and state always produce the same
 * output. It writes into `output` and advances `state` in place because a real
 * audio callback cannot allocate, but it reads nothing else and depends on no
 * module-scope binding — that self-containment is what lets
 * {@link dspWorkletModuleSource} ship this exact function to the audio thread.
 *
 * Out-of-range parameters are clamped rather than rejected: a parameter message
 * arriving mid-stream must never be able to throw on the audio thread.
 */
export function processCrush(
  input: Float32Array,
  output: Float32Array,
  parameters: CrushParameters,
  state: CrushState,
): void {
  const bits = Math.min(16, Math.max(1, Math.round(parameters.bits)));
  const levels = Math.pow(2, bits) - 1;
  const reduction = Math.max(1, Math.floor(parameters.reduction));
  const drive = Math.max(1e-6, parameters.drive);
  const mix = Math.min(1, Math.max(0, parameters.mix));
  let hold = state.hold;
  let phase = state.phase;
  for (let index = 0; index < input.length; index += 1) {
    const dry = input[index] ?? 0;
    if (phase <= 0) {
      // tanh is the cheap soft clip: it saturates smoothly instead of the hard
      // corner that makes clipping sound like a fault rather than an effect.
      const driven = Math.tanh(dry * drive);
      hold = (Math.round((driven + 1) * 0.5 * levels) / levels) * 2 - 1;
      phase = reduction;
    }
    phase -= 1;
    output[index] = dry + (hold - dry) * mix;
  }
  state.hold = hold;
  state.phase = phase;
}

/**
 * The worklet module text, with {@link processCrush} embedded verbatim.
 *
 * Generating the source instead of shipping a second `.js` file keeps the DSP in
 * one place and works regardless of how the engine is bundled — a worklet module
 * is fetched by URL from the audio thread, so a bundler-relative path is exactly
 * the thing that breaks in someone else's build.
 */
export function dspWorkletModuleSource(): string {
  return `const processCrush = ${processCrush.toString()};
const DEFAULTS = ${JSON.stringify(DEFAULT_CRUSH_PARAMETERS)};
class VapourCrushProcessor extends AudioWorkletProcessor {
  constructor(options) {
    super();
    this.parameters = { ...DEFAULTS, ...(options && options.processorOptions) };
    this.states = [];
    this.port.onmessage = (event) => {
      this.parameters = { ...this.parameters, ...event.data };
    };
  }
  process(inputs, outputs) {
    const input = inputs[0];
    const output = outputs[0];
    if (!output) return true;
    for (let channel = 0; channel < output.length; channel += 1) {
      const source = input && (input[channel] || input[0]);
      if (!source) { output[channel].fill(0); continue; }
      if (!this.states[channel]) this.states[channel] = { hold: 0, phase: 0 };
      processCrush(source, output[channel], this.parameters, this.states[channel]);
    }
    return true;
  }
}
registerProcessor(${JSON.stringify(CRUSH_PROCESSOR_NAME)}, VapourCrushProcessor);
`;
}

/** How a DSP node ended up running. */
export type DspMode = "worklet" | "script-processor" | "bypass";

export interface DspWorkletStatus {
  /** True only when the real `AudioWorklet` path is live. */
  readonly ready: boolean;
  readonly mode: DspMode;
  /** Why the worklet path was not taken, for logs and player-facing warnings. */
  readonly reason?: string;
}

/** A DSP effect placed in the graph. `node` is what you connect. */
export interface DspNode {
  readonly mode: DspMode;
  readonly node: AudioNode;
  /** Sends a parameter change to the processor. Safe while audio is running. */
  setParameters(parameters: Partial<CrushParameters>): void;
  readonly parameters: CrushParameters;
  /** Disconnects and releases the node. */
  dispose(): void;
}

const registered = new WeakSet<BaseAudioContext>();

/**
 * Registers the DSP module on a context.
 *
 * Idempotent per context, and never throws for an unsupported browser: the
 * absence of `audioWorklet` is a fact about the environment, not a programming
 * error, and callers need to branch on it rather than catch it. A module that
 * *fails to compile* is a programming error, so that rejection is surfaced in
 * `reason` and leaves the context on the fallback path.
 */
export async function registerDspWorklet(
  context: BaseAudioContext,
  options: { readonly moduleUrl?: string } = {},
): Promise<DspWorkletStatus> {
  if (registered.has(context)) return { ready: true, mode: "worklet" };
  const worklet = (context as BaseAudioContext & { audioWorklet?: AudioWorklet })
    .audioWorklet;
  if (worklet === undefined) {
    return {
      ready: false,
      mode: fallbackMode(context),
      reason:
        "This browser has no AudioWorklet. Vapour DSP falls back to a ScriptProcessor, or to a pass-through when that is missing too.",
    };
  }
  const url = options.moduleUrl ?? objectModuleUrl();
  if (url === undefined) {
    return {
      ready: false,
      mode: fallbackMode(context),
      reason:
        "Blob/URL.createObjectURL are unavailable, so the DSP module could not be published. Pass moduleUrl to register a hosted copy.",
    };
  }
  try {
    await worklet.addModule(url);
    registered.add(context);
    return { ready: true, mode: "worklet" };
  } catch (error) {
    return {
      ready: false,
      mode: fallbackMode(context),
      reason: `AudioWorklet module failed to load: ${error instanceof Error ? error.message : String(error)}`,
    };
  } finally {
    if (options.moduleUrl === undefined) revokeObjectUrl(url);
  }
}

/** True when {@link registerDspWorklet} has succeeded for this context. */
export function isDspWorkletRegistered(context: BaseAudioContext): boolean {
  return registered.has(context);
}

/**
 * Creates the crush effect, using the best path this context supports.
 *
 * Call {@link registerDspWorklet} first; without it this still returns a working
 * node, just on the fallback path. That ordering is deliberate — an effect that
 * refuses to exist until an async registration resolves turns every call site
 * into a promise for no gameplay benefit.
 */
export function createDspNode(
  context: BaseAudioContext,
  parameters: Partial<CrushParameters> = {},
): DspNode {
  let current: CrushParameters = {
    ...DEFAULT_CRUSH_PARAMETERS,
    ...parameters,
  };
  validateCrushParameters(current);

  if (registered.has(context)) {
    const Constructor = (
      globalThis as typeof globalThis & {
        AudioWorkletNode?: typeof AudioWorkletNode;
      }
    ).AudioWorkletNode;
    if (Constructor !== undefined) {
      const node = new Constructor(context, CRUSH_PROCESSOR_NAME, {
        processorOptions: { ...current },
      });
      return {
        mode: "worklet",
        node,
        get parameters() {
          return current;
        },
        setParameters(update) {
          current = merge(current, update);
          node.port.postMessage({ ...current });
        },
        dispose() {
          node.disconnect();
        },
      };
    }
  }

  const legacy = context as BaseAudioContext & {
    createScriptProcessor?: (
      bufferSize: number,
      inputs: number,
      outputs: number,
    ) => ScriptProcessorNode;
  };
  if (typeof legacy.createScriptProcessor === "function") {
    const node = legacy.createScriptProcessor(512, 1, 1);
    const states: CrushState[] = [];
    node.onaudioprocess = (event: AudioProcessingEvent) => {
      const { inputBuffer, outputBuffer } = event;
      for (
        let channel = 0;
        channel < outputBuffer.numberOfChannels;
        channel += 1
      ) {
        const source = inputBuffer.getChannelData(
          Math.min(channel, inputBuffer.numberOfChannels - 1),
        );
        states[channel] ??= { hold: 0, phase: 0 };
        processCrush(
          source,
          outputBuffer.getChannelData(channel),
          current,
          states[channel]!,
        );
      }
    };
    return {
      mode: "script-processor",
      node,
      get parameters() {
        return current;
      },
      setParameters(update) {
        current = merge(current, update);
      },
      dispose() {
        node.onaudioprocess = null;
        node.disconnect();
      },
    };
  }

  const node = context.createGain();
  return {
    mode: "bypass",
    node,
    get parameters() {
      return current;
    },
    setParameters(update) {
      current = merge(current, update);
    },
    dispose() {
      node.disconnect();
    },
  };
}

function merge(
  current: CrushParameters,
  update: Partial<CrushParameters>,
): CrushParameters {
  const next: CrushParameters = { ...current, ...update };
  validateCrushParameters(next);
  return next;
}

/** Rejects nonsense at the API boundary; the audio thread only ever clamps. */
function validateCrushParameters(parameters: CrushParameters): void {
  for (const [key, value] of Object.entries(parameters)) {
    if (!Number.isFinite(value))
      throw new Error(`Crush parameter '${key}' must be finite.`);
  }
  if (parameters.mix < 0 || parameters.mix > 1)
    throw new Error("Crush parameter 'mix' must lie in [0, 1].");
  if (parameters.bits < 1 || parameters.bits > 16)
    throw new Error("Crush parameter 'bits' must lie in [1, 16].");
  if (parameters.reduction < 1)
    throw new Error("Crush parameter 'reduction' must be at least 1.");
  if (parameters.drive <= 0)
    throw new Error("Crush parameter 'drive' must be positive.");
}

function fallbackMode(context: BaseAudioContext): DspMode {
  return typeof (context as { createScriptProcessor?: unknown })
    .createScriptProcessor === "function"
    ? "script-processor"
    : "bypass";
}

function objectModuleUrl(): string | undefined {
  if (typeof Blob !== "function" || typeof URL?.createObjectURL !== "function")
    return undefined;
  return URL.createObjectURL(
    new Blob([dspWorkletModuleSource()], { type: "text/javascript" }),
  );
}

function revokeObjectUrl(url: string): void {
  if (typeof URL?.revokeObjectURL === "function") URL.revokeObjectURL(url);
}
